# Sum of all integers from 1 to 902 inclusive that are divisible by 8 or by 7

def sum_divisible_by(n, limit):
    """Sum of multiples of n up to limit"""
    k = limit // n
    return n * k * (k + 1) // 2

def sum_divisible_by_8_or_7(limit):
    # Inclusion-exclusion: sum(div by 8) + sum(div by 7) - sum(div by lcm(8,7)=56)
    return sum_divisible_by(8, limit) + sum_divisible_by(7, limit) - sum_divisible_by(56, limit)

